const imageViewer=document.createElement('dialog');imageViewer.id='image-viewer';imageViewer.innerHTML='<button type="button" class="dialog-close" data-dismiss aria-label="Close image viewer">×</button><div class="image-viewer-tools"><button type="button" data-zoom="out" aria-label="Zoom out">−</button><button type="button" data-zoom="in" aria-label="Zoom in">＋</button><button type="button" data-zoom="reset">Fit</button><button type="button" id="viewer-copy">Copy image</button></div><div class="image-stage"><img alt="Enlarged saved image" draggable="false"></div>';document.body.append(imageViewer);
const imageStage=imageViewer.querySelector('.image-stage'),viewerImage=imageStage.querySelector('img');let viewerRecord=null,imageScale=1,imageX=0,imageY=0,imageDrag=null;
function paintImage(){viewerImage.style.transform=`translate(${imageX}px,${imageY}px) scale(${imageScale})`}
function zoomImage(factor){imageScale=Math.max(.25,Math.min(12,imageScale*factor));paintImage()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-enlarge]');if(!b)return;viewerRecord=data().find(r=>r.id===b.dataset.enlarge);if(!viewerRecord?.images?.[0])return;viewerImage.src=imageURL(viewerRecord.images[0]);imageScale=1;imageX=imageY=0;paintImage();imageViewer.showModal()});
imageViewer.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{if(b.dataset.zoom==='reset'){imageScale=1;imageX=imageY=0;paintImage()}else zoomImage(b.dataset.zoom==='in'?1.25:.8)});imageViewer.querySelector('#viewer-copy').onclick=()=>copyRecord(viewerRecord,'image');
const imagePointers=new Map();let imageGesture=null;
function gestureSnapshot(){const points=[...imagePointers.values()];if(points.length<2)return null;const [a,b]=points;return {x:(a.x+b.x)/2,y:(a.y+b.y)/2,distance:Math.max(1,Math.hypot(a.x-b.x,a.y-b.y))}}
function zoomAt(factor,x,y){const rect=imageStage.getBoundingClientRect(),px=x-rect.left-rect.width/2,py=y-rect.top-rect.height/2,next=Math.max(.25,Math.min(12,imageScale*factor)),ratio=next/imageScale;imageX=px-(px-imageX)*ratio;imageY=py-(py-imageY)*ratio;imageScale=next;paintImage()}
imageStage.addEventListener('wheel',e=>{e.preventDefault();if(e.ctrlKey)zoomAt(Math.exp(-e.deltaY*.01),e.clientX,e.clientY);else{imageX-=e.deltaX;imageY-=e.deltaY;paintImage()}},{passive:false});
imageStage.onpointerdown=e=>{if(e.pointerType==='mouse'&&e.button!==0)return;imagePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});imageStage.setPointerCapture(e.pointerId);imageGesture=gestureSnapshot()};
imageStage.onpointermove=e=>{const previous=imagePointers.get(e.pointerId);if(!previous)return;imagePointers.set(e.pointerId,{x:e.clientX,y:e.clientY});const next=gestureSnapshot();if(next&&imageGesture){zoomAt(next.distance/imageGesture.distance,imageGesture.x,imageGesture.y);imageX+=next.x-imageGesture.x;imageY+=next.y-imageGesture.y;paintImage()}else if(!next&&e.pointerType!=='touch'){imageX+=e.clientX-previous.x;imageY+=e.clientY-previous.y;paintImage()}imageGesture=next};
imageStage.onpointerup=imageStage.onpointercancel=imageStage.onlostpointercapture=e=>{imagePointers.delete(e.pointerId);imageGesture=gestureSnapshot()};
imageViewer.addEventListener('close',()=>{imagePointers.clear();imageGesture=null});


window.updateCaptureAction=()=>{const button=composer.querySelector('[type=submit]'),empty=!$('capture').value.trim()&&!pendingImages.length;button.innerHTML=(empty?'Auto paste inn':'Paste inn')+' <span aria-hidden="true">↵</span>';button.title=empty?'Read your clipboard and save it to the selected crate':'Save this note and any attachments to the selected crate';button.setAttribute('aria-label',empty?'Auto paste inn':'Paste inn')};
$('capture').addEventListener('input',updateCaptureAction);new MutationObserver(updateCaptureAction).observe($('pending-images'),{childList:true,attributes:true,attributeFilter:['hidden']});updateCaptureAction();
const inputDescriptions={'auto-paste':'Read your clipboard and save it to this crate','add-image':'Attach images, audio, or video','take-photo':'Take a photo and attach it','record-voice':'Record a voice note; tap again to stop','edit-categories':'Add or customize crates','previous-category':'Choose the previous crate','next-category':'Choose the next crate'};
for(const [id,description] of Object.entries(inputDescriptions)){const button=$(id);button.title=description;button.dataset.tip=description;button.addEventListener('mouseenter',()=>showInputTip(button));button.addEventListener('mouseleave',hideInputTip);button.addEventListener('focus',()=>showInputTip(button));button.addEventListener('blur',hideInputTip)}
const inputTip=document.createElement('div');inputTip.className='input-tip';inputTip.id='input-button-tip';inputTip.setAttribute('role','tooltip');inputTip.hidden=true;document.body.append(inputTip);
function showInputTip(button){inputTip.textContent=button.dataset.tip;inputTip.hidden=false;const r=button.getBoundingClientRect(),w=inputTip.getBoundingClientRect().width;inputTip.style.left=Math.max(8,Math.min(innerWidth-w-8,r.left+r.width/2-w/2))+'px';inputTip.style.top=Math.max(8,r.top-inputTip.getBoundingClientRect().height-9)+'px';button.setAttribute('aria-describedby',inputTip.id)}
function hideInputTip(){inputTip.hidden=true;document.querySelectorAll('[aria-describedby="input-button-tip"]').forEach(b=>b.removeAttribute('aria-describedby'))}addEventListener('scroll',hideInputTip,true);

$('quick-card-size').onchange=async e=>{const control=e.target;control.disabled=true;try{await InnSurface.setCardLayout(control.value,onlyCategory?categories[selected].id:'global')}catch{toast('Couldn’t save the card size. Try again.');render()}finally{control.disabled=false}};

document.addEventListener('click',e=>{const source=e.target.closest('.card-main[data-source]');if(source&&!e.target.closest('button,a,iframe,audio,video'))window.open(source.dataset.source,'_blank','noopener,noreferrer')});
